-- Nexmark q5 on flink, KAFKA-SINK sink variant. Hot items: the single most-
-- bid-on auction per 10s sliding window, advancing 2s. Sliding window
-- aggregate feeding a top-1 rank. NOTE the argument orders differ and are NOT
-- interchangeable: clink is HOP(time, SIZE, SLIDE) while Flink's table
-- function is HOP(TABLE, DESCRIPTOR, SLIDE, SIZE). Getting it backwards makes
-- slide exceed size, which the operator rejects.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (
  `auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING, `url` STRING, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-bid',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-q5-bid',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE sink_q5 (`wstart` BIGINT, `auction` BIGINT, `num` BIGINT) WITH (
  'connector' = 'kafka',
  'topic' = '__OUT__',
  'properties.bootstrap.servers' = 'kafka:29092',
  'format' = 'json',
  'sink.delivery-guarantee' = 'at-least-once'
);
INSERT INTO sink_q5
SELECT wstart, auction, num FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY wstart ORDER BY num DESC) AS rn FROM (SELECT auction, COUNT(*) AS num, window_start AS wstart FROM TABLE(HOP(TABLE bid, DESCRIPTOR(ts), INTERVAL '2' SECOND, INTERVAL '10' SECOND)) GROUP BY window_start, window_end, auction) AS W) AS R WHERE rn <= 1;
